using OfficeIMO.Drawing;
using OfficeIMO.Html;
using OfficeIMO.Html.Pdf;
using OfficeIMO.Pdf;
using System.Security.Cryptography;
using System.Text.Json;

// Scratch v2 public observer; only exact copied local font resources are resolvable.
string inputs = Path.GetFullPath(args[0]);
string output = Path.GetFullPath(args[1]);
string sourceHead = args[2];
if (args.Length != 3 && (args.Length != 5 || args[3] != "--fixtures"))
    throw new ArgumentException("Usage: PageMarginProbe <inputs> <fresh-output> <source-sha> [--fixtures <case-id,...>]");
string[] selectedFixtures = args.Length == 5
    ? args[4].Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
    : Array.Empty<string>();
string[] inputFiles = Directory.GetFiles(inputs, "*.html").OrderBy(p => p, StringComparer.Ordinal).ToArray();
bool Matches(string path, string selector) => Path.GetFileNameWithoutExtension(path) == selector
    || Path.GetFileNameWithoutExtension(path) == selector + "-expanded";
if (args.Length == 5 && (selectedFixtures.Length == 0 || selectedFixtures.Any(selector => !inputFiles.Any(path => Matches(path, selector)))))
    throw new ArgumentException("Every --fixtures selector must match an existing case or exact variant name.");
if (selectedFixtures.Length > 0) inputFiles = inputFiles.Where(path => selectedFixtures.Any(selector => Matches(path, selector))).ToArray();
if (Directory.Exists(output)) throw new IOException("Fresh output required; preserve prior observations.");
Directory.CreateDirectory(output);
byte[] regular = File.ReadAllBytes(Path.Combine(inputs, "regular.ttf"));
byte[] bold = File.ReadAllBytes(Path.Combine(inputs, "bold.ttf"));
byte[] gap = File.ReadAllBytes(Path.Combine(inputs, "gap.ttf"));
var fontFiles = new Dictionary<string, (string Path, byte[] Bytes)>(StringComparer.Ordinal) {
    [new Uri(Path.Combine(inputs, "regular.ttf")).AbsoluteUri] = (Path.Combine(inputs, "regular.ttf"), regular),
    [new Uri(Path.Combine(inputs, "bold.ttf")).AbsoluteUri] = (Path.Combine(inputs, "bold.ttf"), bold),
    [new Uri(Path.Combine(inputs, "gap.ttf")).AbsoluteUri] = (Path.Combine(inputs, "gap.ttf"), gap)
};
var localFontPolicy = new HtmlUrlPolicy {
    DisallowFileUrls = false, AllowDataUrls = false, AllowMailtoUrls = false,
    AllowProtocolRelativeUrls = false, RestrictUrlSchemes = true
};
localFontPolicy.AllowedUrlSchemes.Clear();
localFontPolicy.AllowedUrlSchemes.Add(Uri.UriSchemeFile);
var rows = new List<object>();
foreach (string input in inputFiles) {
    string name = Path.GetFileNameWithoutExtension(input);
    Uri baseUri = new Uri(input);
    var document = HtmlConversionDocument.Parse(File.ReadAllText(input), new HtmlConversionDocumentOptions {
        BaseUri = baseUri, ResourceUrlPolicy = localFontPolicy
    });
    foreach (var profile in new[] { HtmlRenderIntentProfile.PrintPaged, HtmlRenderIntentProfile.ScreenMediaPaged }) {
        string directory = Path.Combine(output, name, profile.ToString());
        Directory.CreateDirectory(directory);
        var resourceRequests = new List<object>();
        string phase = "Png";
        HtmlRenderResourceResolver exactFontResolver = (request, cancellationToken) => {
            cancellationToken.ThrowIfCancellationRequested();
            bool accepted = request.Kind == HtmlResourceKind.Font && request.Uri.IsFile
                && fontFiles.TryGetValue(request.Uri.AbsoluteUri, out _);
            lock (resourceRequests) resourceRequests.Add(new {
                phase, uri = request.Uri.AbsoluteUri, kind = request.Kind.ToString(), accepted,
                file = accepted ? FileBinding(fontFiles[request.Uri.AbsoluteUri].Path) : null
            });
            return Task.FromResult<HtmlResolvedResource?>(accepted
                ? new HtmlResolvedResource(fontFiles[request.Uri.AbsoluteUri].Bytes, "font/ttf") : null);
        };
        var options = new HtmlToPdfOptions {
            ViewportWidth = 360, ViewportHeight = 480,
            PageSize = new OfficePageSize(360D / 96D, 480D / 96D),
            Margins = HtmlRenderMargins.All(0),
            DefaultFontFamily = "MetricWitness", AllowSystemFontFallback = false,
            BaseUri = baseUri, ResourceUrlPolicy = localFontPolicy, ResourceResolver = exactFontResolver,
            ResourcePolicy = new PdfResourcePolicy {
                AllowLocalFileAccess = true, AllowDataUris = false, AllowEmbeddedPackageResources = false,
                AllowSystemFontEmbedding = false, AllowDocumentFontEmbedding = false, AllowRemoteResourceResolution = false
            },
            UserAgentStyles = HtmlRenderUserAgentStyleMode.Browser,
            FontFamily = new PdfEmbeddedFontFamily("MetricWitness", regular, bold)
        };
        options.Fonts.Add("MetricWitness", regular);
        options.Fonts.Add("MetricWitness", bold, OfficeFontStyle.Bold);
        options.Fonts.Add("MetricGap", gap);
        var rendered = await HtmlRenderEngine.ExecuteAsync(document, HtmlRenderRequest.Create(profile, HtmlRenderEncoder.Png, options));
        phase = "Pdf";
        byte[] pdf = (await document.RenderToPdfResultAsync(HtmlRenderRequest.Create(profile, HtmlRenderEncoder.Pdf, options))).ToBytes();
        string pdfPath = Path.Combine(directory, "document.pdf");
        File.WriteAllBytes(pdfPath, pdf);
        var direct = rendered.ExportImages();
        var saved = PdfReadDocument.Open(pdf, new PdfLoadOptions { IncludeArtifactText = true });
        var replay = saved.ExportImages(OfficeImageExportFormat.Png, new PdfImageExportOptions { Scale = 96D / 72D });
        var images = new List<object>();
        bool ownEqual = direct.Count == replay.Count;
        for (int index = 0; index < direct.Count; index++) {
            string directPath = Path.Combine(directory, $"direct-{index + 1:D2}.png");
            File.WriteAllBytes(directPath, direct[index].Bytes);
            bool equal = index < replay.Count && direct[index].Bytes.SequenceEqual(replay[index].Bytes);
            ownEqual &= equal;
            string replayPath = Path.Combine(directory, $"pdf-replay-{index + 1:D2}.png");
            if (index < replay.Count) File.WriteAllBytes(replayPath, replay[index].Bytes);
            images.Add(new { page = index + 1, direct = FileBinding(directPath), replay = index < replay.Count ? FileBinding(replayPath) : null, encodedBytesEqual = equal });
        }
        rows.Add(new {
            fixture = name, profile = profile.ToString(), input = FileBinding(input),
            baseUri = baseUri.AbsoluteUri, resourceRequests,
            resourcePolicy = new { allowedSchemes = new[] { "file" }, exactFontFileCount = fontFiles.Count,
                localFileAccess = true, systemFonts = false, documentHostFonts = false, remote = false },
            pages = rendered.Document.Pages.Count, pdfPages = saved.Pages.Count,
            ownPngPdfReplayEqual = ownEqual, pdf = FileBinding(pdfPath), images,
            scene = rendered.Document.Pages.Select(page => new {
                page.PageNumber, page.Width, page.Height, page.Margins,
                text = Walk(page.Scene).OfType<HtmlRenderText>().Select(text => new {
                    text.Source, text.SemanticRole, text.Text, text.X, text.Y, text.Width, text.Height,
                    text.TextAdvanceWidth, text.TextPaintWidth, alignment = text.Alignment.ToString(),
                    text.LineHeight, fontFamily = text.Font.FamilyName, fontSize = text.Font.Size,
                    fontStyle = text.Font.Style.ToString(), text.Baseline, text.BaselineOffset
                }).ToArray(),
                drawingText = DrawingTextObservations(page.CreateDrawing(), "page", Array.Empty<object>()).ToArray()
            }).ToArray(),
            savedPdfSpans = saved.Pages.Select((page, index) => new {
                page = index + 1, spans = page.GetTextSpans().Select(span => new { span.Text, span.X, span.Y, span.Advance }).ToArray()
            }).ToArray(),
            diagnostics = rendered.Document.Diagnostics.Select(d => new { d.Code, d.Source, d.Severity, d.LossKind }).ToArray()
        });
    }
}
var runtime = AppDomain.CurrentDomain.GetAssemblies()
    .Where(a => !a.IsDynamic && (a.GetName().Name!.StartsWith("OfficeIMO.", StringComparison.Ordinal) || a.GetName().Name!.StartsWith("AngleSharp", StringComparison.Ordinal)))
    .Select(a => FileBinding(a.Location)).ToArray();
File.WriteAllText(Path.Combine(output, "summary.json"), JsonSerializer.Serialize(new {
    declaredSourceHead = sourceHead, publicApiOnly = true, ambientFontFallbackEnabled = false,
    selectedFixtures, selectedInputFiles = inputFiles.Select(FileBinding).ToArray(),
    resourceBoundary = "File BaseUri plus public async resolver accepting only the three exact copied font file URIs/snapshots. No remote, data or ambient font resources.",
    regular = FileBinding(Path.Combine(inputs, "regular.ttf")), bold = FileBinding(Path.Combine(inputs, "bold.ttf")),
    gap = FileBinding(Path.Combine(inputs, "gap.ttf")), runtime, rows,
    boundary = "Observation only: actual author line-height/native comparisons require ROOT adjudication. PDF artifact text included; spatial spans are geometry observations."
}, new JsonSerializerOptions { WriteIndented = true }));
Console.WriteLine($"Captured {rows.Count} input/profile observations; failures remain visible in summary.json.");
static object FileBinding(string path) => new { path, bytes = new FileInfo(path).Length, sha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path))).ToLowerInvariant() };
static IEnumerable<object> DrawingTextObservations(OfficeDrawing drawing, string path, IReadOnlyList<object> ancestors) {
    for (int index = 0; index < drawing.Elements.Count; index++) {
        var element = drawing.Elements[index];
        string itemPath = path + "/" + index;
        if (element is OfficeDrawingText text) {
            yield return new {
                path = itemPath, coordinateSpace = ancestors.Count == 0 ? "page" : "nested-group-local",
                ancestors, text.Text, text.X, text.Y, text.Width, text.Height,
                text.TextAdvanceWidth, alignment = text.Alignment.ToString(), text.LineHeight,
                fontFamily = text.Font.FamilyName, fontSize = text.Font.Size
            };
        } else if (element is OfficeDrawingGroup group) {
            object frame = new { kind = "clip-group", group.X, group.Y, group.ContentOffsetX, group.ContentOffsetY, group.FrameTransform };
            foreach (var child in DrawingTextObservations(group.Drawing, itemPath, ancestors.Concat(new[] { frame }).ToArray())) yield return child;
        } else if (element is OfficeDrawingEffectGroup effect) {
            object frame = new { kind = "effect-group", effect.Transform, effect.Opacity };
            foreach (var child in DrawingTextObservations(effect.Drawing, itemPath, ancestors.Concat(new[] { frame }).ToArray())) yield return child;
        }
    }
}
static IEnumerable<HtmlRenderVisual> Walk(IEnumerable<HtmlRenderVisual> source) {
    foreach (var item in source) {
        yield return item;
        IEnumerable<HtmlRenderVisual>? children = item switch {
            HtmlRenderClipGroup x => x.Visuals, HtmlRenderPathClipGroup x => x.Visuals,
            HtmlRenderSemanticGroup x => x.Visuals, HtmlRenderEffectGroup x => x.Visuals,
            HtmlRenderLogicalTextGroup x => x.Visuals, HtmlRenderLayoutRegion x => x.Visuals,
            HtmlRenderFormField x => x.Visuals, _ => null
        };
        if (children != null) foreach (var child in Walk(children)) yield return child;
    }
}

